import { assertHashParams, GET_P2SH_OP_0 } from './utils/assertHash.mjs'
import { toWebCryptoDigestType } from './utils/browserHashTools.mjs'
import { combineHashInput } from './utils/input.mjs'
import { fromUint8Super } from './utils/output.mjs'
import { hashSync } from './hash.native.mjs'

export { hashSync } from './hash.native.mjs'

const crypto = globalThis.crypto

export async function hash(type, data, form = 'buffer') {
  assertHashParams(type, form)
  data = combineHashInput(data) // eslint-disable-line no-param-reassign

  if (type === 'hash160') return hashSync('ripemd160', await hash('sha256', data), form)
  if (type === 'p2sh-hash160') {
    return hash('hash160', [GET_P2SH_OP_0(data), await hash('hash160', data)], form)
  }
  const algo = toWebCryptoDigestType(type)
  if (!algo) return hashSync(type, data, form)
  const result = await crypto.subtle.digest(algo, data)
  return fromUint8Super(new Uint8Array(result), form)
}
